// Read-only counters and fixed event classifications; never reads pixel buffers.
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <dirent.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#define ROOT "/tmp/kobo-android-runtime"
#define READY ROOT "/lab/interactive-session-ready"
static volatile sig_atomic_t stopped;
static void stop(int n){(void)n;stopped=1;}
static double now(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}
static int load(const char *p,char *b,size_t cap){int f=open(p,O_RDONLY|O_CLOEXEC|O_NOFOLLOW);if(f<0)return -1;ssize_t n=read(f,b,cap-1);close(f);if(n<0)return -1;b[n]=0;return (int)n;}
static int link_is(int p,const char *field,const char *expected){char path[80],b[512];snprintf(path,sizeof path,"/proc/%d/%s",p,field);ssize_t n=readlink(path,b,sizeof b-1);if(n<0)return 0;b[n]=0;return !strcmp(b,expected);}
struct proc {int pid;unsigned long long born;char role[12];};
static struct proc actors[16];static int count;
static int procstat(int p,unsigned long long v[50],char *state){char path[80],b[4096];snprintf(path,sizeof path,"/proc/%d/stat",p);if(load(path,b,sizeof b)<0)return -1;char *end=strrchr(b,')');if(!end||end[1]!=' '||!end[2])return -1;*state=end[2];char *save=0,*s=end+4;int field=4;memset(v,0,50*sizeof *v);for(char *t=strtok_r(s," ",&save);t&&field<50;t=strtok_r(0," ",&save))v[field++]=strtoull(t,0,10);return field>24?0:-1;}
static void discover(void){DIR *d=opendir("/proc");if(!d)return;count=0;struct dirent *e;while(count<16&&(e=readdir(d))){char *end;long p=strtol(e->d_name,&end,10);if(*end||p<=0||p>2147483647)continue;if(!link_is((int)p,"root",ROOT)||!link_is((int)p,"exe",ROOT "/system/bin/app_process32"))continue;char path[80],b[4096];snprintf(path,sizeof path,"/proc/%ld/status",p);if(load(path,b,sizeof b)<0)continue;char *u=strstr(b,"\nUid:");unsigned uid;if(!u||sscanf(u,"\nUid: %u",&uid)!=1)continue;const char *role=0;if(uid==1000)role="system";else if(uid==10007){snprintf(path,sizeof path,"/proc/%ld/cmdline",p);if(load(path,b,sizeof b)<=0)continue;if(!strcmp(b,"com.tencent.weread.eink"))role="main";else if(!strcmp(b,"com.tencent.weread.eink:seg"))role="seg";}if(!role)continue;unsigned long long v[50];char state;if(procstat((int)p,v,&state))continue;actors[count].pid=(int)p;actors[count].born=v[22];snprintf(actors[count].role,sizeof actors[count].role,"%s",role);count++;}closedir(d);}
static void process_sample(double t,int p,unsigned long long born,const char *role){unsigned long long v[50],check[50];char state,again;if(procstat(p,v,&state)||v[22]!=born||!link_is(p,"root",ROOT)||!link_is(p,"exe",ROOT "/system/bin/app_process32"))return;char path[80],b[4096];unsigned long long rb=0,wb=0;int io_available=0;snprintf(path,sizeof path,"/proc/%d/io",p);if(load(path,b,sizeof b)>0){io_available=1;char *x=strstr(b,"read_bytes:");if(x)sscanf(x,"read_bytes: %llu",&rb);x=strstr(b,"write_bytes:");if(x)sscanf(x,"write_bytes: %llu",&wb);}snprintf(path,sizeof path,"/proc/%d/wchan",p);char wait[80]="unavailable";if(load(path,b,sizeof b)>0){size_t n=strcspn(b,"\n ");if(n<sizeof wait){memcpy(wait,b,n);wait[n]=0;}}if(procstat(p,check,&again)||check[22]!=born)return;printf("process t=%.3f role=%s pid=%d born=%llu state=%c utime=%llu stime=%llu minflt=%llu majflt=%llu rss_pages=%llu threads=%llu io_available=%d read_bytes=%llu write_bytes=%llu wchan=%s\n",t,role,p,born,state,v[14],v[15],v[10],v[12],v[24],v[20],io_available,rb,wb,wait);}
struct tail {const char *path;off_t offset;ino_t inode;int kind;};
static unsigned gc_count,fatal_count,anr_count,gestures;static double gc_ms;
static void tail_events(struct tail *l,double t){FILE *f=fopen(l->path,"r");if(!f)return;struct stat st;if(fstat(fileno(f),&st)||!S_ISREG(st.st_mode)){fclose(f);return;}if(l->inode!=st.st_ino||st.st_size<l->offset){l->inode=st.st_ino;l->offset=st.st_size;fclose(f);return;}if(fseeko(f,l->offset,SEEK_SET)){fclose(f);return;}char b[2048];unsigned used=0;while(used<262144&&fgets(b,sizeof b,f)){off_t next=ftello(f);used+=(unsigned)(next-l->offset);if(!strchr(b,'\n')){l->offset=next;continue;}l->offset=next;if(l->kind==0){if(strstr(b," GC ")&&strstr(b," total ")){gc_count++;char *x=strstr(b," total ");double n;char unit[8];if(sscanf(x," total %lf%7s",&n,unit)==2)gc_ms+=!strncmp(unit,"ms",2)?n:unit[0]=='s'?n*1000:0;}if(strstr(b,"FATAL EXCEPTION")||strstr(b,"Fatal signal "))fatal_count++;if(strstr(b,"ANR in com.tencent.weread.eink"))anr_count++;const char *activity=strstr(b,"com.tencent.weread.eink/com.tencent.weread.ReaderFragmentActivity")?"reader":strstr(b,"com.tencent.weread.eink/com.tencent.weread.WeReadFragmentActivity")?"bookshelf":0;if(activity&&(strstr(b,"START u0 ")||strstr(b,"Displayed ")))printf("activity t=%.3f kind=%s event=%s\n",t,activity,strstr(b,"Displayed ")?"displayed":"start");}else if(l->kind==1){unsigned frame,seq;double stamp,paint;char *x=strstr(b,"monotonic="),*y=strstr(b,"paint_ms="),wave[12];if(sscanf(b,"LIVE_DISPLAY_FRAME frame=%u sequence=%u",&frame,&seq)==2&&x&&y&&sscanf(x,"monotonic=%lf",&stamp)==1&&sscanf(y,"paint_ms=%lf waveform=%11s",&paint,wave)==2)printf("paint t=%.3f frame=%u sequence=%u paint_ms=%.1f waveform=%s\n",stamp,frame,seq,paint,wave);}else if(strstr(b,"ANDROID_WEREAD_INTERACTIVE_GESTURE_DISPATCHED")){gestures++;printf("gesture t=%.3f number=%u\n",t,gestures);}}
 fclose(f);}
int main(int argc,char **argv){char *end;if(argc!=2||geteuid()!=0)return 2;long seconds=strtol(argv[1],&end,10);if(*end||seconds<10||seconds>1800)return 2;struct stat initial,current;if(lstat(READY,&initial)||!S_ISREG(initial.st_mode)||initial.st_uid!=0)return 3;signal(SIGINT,stop);signal(SIGTERM,stop);signal(SIGHUP,stop);setvbuf(stdout,0,_IOLBF,0);struct tail logs[]={{ROOT "/lab/android.log",0,0,0},{ROOT "/lab/native-resolution/live-display.log",0,0,1},{ROOT "/lab/touch-probe.log",0,0,2}};printf("SAMPLER_BEGIN t=%.3f hz=%ld page_bytes=%ld interval_seconds=1 max_seconds=%ld\n",now(),sysconf(_SC_CLK_TCK),sysconf(_SC_PAGESIZE),seconds);char boot[128];if(load("/proc/uptime",boot,sizeof boot)>0){double up;if(sscanf(boot,"%lf",&up)==1)printf("CLOCK_PAIR monotonic=%.3f boot_uptime=%.2f\n",now(),up);}
 double deadline=now()+seconds;unsigned samples=0;double sampler_ms=0;while(!stopped&&now()<deadline){if(lstat(READY,&current)||current.st_ino!=initial.st_ino||current.st_dev!=initial.st_dev)break;double begin=now();if(samples%5==0)discover();double t=now();char b[4096];if(load("/proc/stat",b,sizeof b)>0){char *n=strchr(b,'\n');if(n)*n=0;printf("host_cpu t=%.3f %s\n",t,b);}if(load("/proc/diskstats",b,sizeof b)>0){char *save=0;for(char *line=strtok_r(b,"\n",&save);line;line=strtok_r(0,"\n",&save)){char dev[32];unsigned major,minor;if(sscanf(line,"%u %u %31s",&major,&minor,dev)==3&&!strcmp(dev,"mmcblk0"))printf("host_disk t=%.3f %s\n",t,line);}}if(load("/proc/meminfo",b,sizeof b)>0){char *a=strstr(b,"MemAvailable:");unsigned long n;if(a&&sscanf(a,"MemAvailable: %lu",&n)==1)printf("memory t=%.3f available_kib=%lu\n",t,n);}for(int i=0;i<count;i++)process_sample(t,actors[i].pid,actors[i].born,actors[i].role);unsigned long long own[50];char state;if(!procstat(getpid(),own,&state))printf("sampler_cpu t=%.3f utime=%llu stime=%llu\n",t,own[14],own[15]);for(unsigned i=0;i<sizeof logs/sizeof logs[0];i++)tail_events(&logs[i],t);printf("cumulative t=%.3f gc_count=%u gc_total_ms=%.1f fatal=%u anr=%u gestures=%u\n",t,gc_count,gc_ms,fatal_count,anr_count,gestures);sampler_ms+=(now()-begin)*1000;samples++;struct timespec delay={0,0};double wait=1-(now()-begin);if(wait>0){delay.tv_sec=(time_t)wait;delay.tv_nsec=(long)((wait-delay.tv_sec)*1e9);nanosleep(&delay,0);}}
 printf("SAMPLER_END t=%.3f samples=%u collection_wall_ms=%.1f\n",now(),samples,sampler_ms);return 0;}
